#include "lab_real_mpusvc_posix.h"
#include <stdio.h>
#include <string.h>
int main(int argc,char **argv){
 if(argc==2&&!strcmp(argv[1],"--help")){puts("lab-mpu9250-info --snapshot /run/acg138-mpu-service/mpu9250.snapshot\nlab-mpu9250-info --legacy /run/acg138-mpu-service/odometry.shm\nlab-mpu9250-info --history /run/acg138-mpu-service/mpu9250.history\nRead-only files; never binds UDP or sends commands.");return 0;}
 if(argc!=3)return 2;
 if(!strcmp(argv[1],"--legacy")){struct odom_shared s;lab_status r=mpusvc_legacy_read(argv[2],&s);if(r!=LAB_OK){fprintf(stderr,"LEGACY_READ_FAILED status=%d\n",r);return 3;}printf("legacy_abi=ODOM1 version=%u bytes=%u sequence=%u pose_session=%u accepted=%u stamp_ms=%llu x=%.6f y=%.6f yaw=%.3f distance=%.6f quality=%u calibrated_declared=%u RAW_IMU_NOT_IN_LEGACY_SNAPSHOT\n",s.version,s.bytes,s.sequence,s.state.session,s.state.accepted,(unsigned long long)s.state.stamp_ms,s.state.x,s.state.y,s.state.heading*57.295779513,s.state.total_distance,s.state.quality,s.state.calibrated);return 0;}
 if(!strcmp(argv[1],"--history")){mpusvc_history_cursor c={0};mpusvc_view v={0};uint8_t b[768];lab_status status=LAB_AGAIN;for(unsigned n=0;n<MPUSVC_HISTORY_CAPACITY;n++){status=mpusvc_history_next(argv[2],&c,b,&v);if(status!=LAB_OK)break;}if(status<0){fprintf(stderr,"HISTORY_READ_FAILED status=%d rows=%llu invalid=%llu\n",status,(unsigned long long)c.rows,(unsigned long long)c.rejected_rows);return 3;}printf("history_capacity=%u history_rows=%llu export_last=%llu original_raw_rx_us=%llu latest_version_jumps=%llu history_overwrites=%llu\n",MPUSVC_HISTORY_CAPACITY,(unsigned long long)c.rows,(unsigned long long)c.sequence,(unsigned long long)v.raw_received_us,(unsigned long long)c.latest_version_jumps,(unsigned long long)c.overwritten);if(c.rows)mpusvc_print(&v,mpusvc_now());return 0;}
 if(strcmp(argv[1],"--snapshot"))return 2;mpusvc_view v;lab_status r=mpusvc_read(argv[2],&v);if(r!=LAB_OK){fprintf(stderr,"SNAPSHOT_READ_FAILED status=%d\n",r);return 3;}mpusvc_print(&v,mpusvc_now());
 printf("pose_FPGA_us=%llu pose_RK_rx_us=%llu ag_FPGA_us=%llu ag_RK_first_seen_us=%llu mag_FPGA_us=%llu mag_RK_first_seen_us=%llu config_crc=%08x parameter_version=%llu\n",(unsigned long long)v.pose_fpga_us,(unsigned long long)v.pose_received_us,(unsigned long long)v.ag_fpga_us,(unsigned long long)v.ag_received_us,(unsigned long long)v.mag_fpga_us,(unsigned long long)v.mag_received_us,v.config_crc,(unsigned long long)v.parameter_version);
 printf("rpy_rad=%.6f,%.6f,%.6f accel_g=%.6f,%.6f,%.6f gyro_rad_s=%.6f,%.6f,%.6f bias_rad_s=%.6f,%.6f,%.6f mag_uT=%.3f,%.3f,%.3f rpm=%.3f,%.3f,%.3f,%.3f temperature_C=%.2f record_count=%llu\n",v.rpy[0],v.rpy[1],v.rpy[2],v.accel[0],v.accel[1],v.accel[2],v.gyro[0],v.gyro[1],v.gyro[2],v.bias[0],v.bias[1],v.bias[2],v.mag[0],v.mag[1],v.mag[2],v.rpm[0],v.rpm[1],v.rpm[2],v.rpm[3],v.temperature,(unsigned long long)v.record_count);return 0;
}
